13	/// Options governing how a version plan is applied to the workspace.
14	#[derive(Clone, Debug, Default)]
15	pub struct ApplyOptions {
16	    /// Plumbed from `--refresh-lockfiles` but not yet consulted here;
17	    /// `ApplyOutcome::lockfile_refresh_results` is consequently always `None`.
18	    pub refresh_lockfiles: bool,
19	}
20	
21	/// The result of a successful [`apply_version_plan`] call, describing which paths were written and staged.
22	#[derive(Clone, Debug, Default)]
23	pub struct ApplyOutcome {
24	    /// Reserved for lockfile refresh results; currently always `None`.
25	    pub lockfile_refresh_results: Option<Vec<LockfileRefreshResult>>,
26	    /// Paths written and staged via `git add`, relative to the workspace root.
27	    pub staged: Vec<PathBuf>,
28	}
29	
30	/// Writes `plan` to disk and stages the touched paths in git.
31	///
32	/// Every side effect this performs is unconditional -- the decision of whether
33	/// to apply at all belongs to the caller, which is why an [`ApplyPermit`] is
34	/// required rather than a `dry_run` flag being passed in. The previous
35	/// `ApplyOptions::transient` field was that flag, and being a plain bool it
36	/// carried no guarantee that any caller consulted it before constructing the
37	/// options. A dry-run caller now cannot obtain a permit and simply does not
38	/// call this function; it reports `plan` instead.
39	///
40	/// # Errors
41	///
42	/// - Manifest parse or write failures (malformed TOML/JSON, unsupported format).
43	/// - Git subprocess failures (`git add` or `git rm --cached` returns a non-zero exit code).
44	/// - I/O errors writing changelog sections or `pre.json`.
45	pub fn apply_version_plan<R: CommandRunner>(
46	    root: &Path,
47	    plan: &VersionPlan,
48	    runner: &R,
49	    opts: &ApplyOptions,
50	    permit: &ApplyPermit,
51	) -> Result<ApplyOutcome, GraphError> {
52	    let mut outcome = ApplyOutcome::default();
53	    let mut modified_paths = Vec::new();
54	
55	    let cargo_workspace = if root.join("Cargo.toml").exists() {
56	        if let Ok(resolver) = WorkspaceCargoResolver::load(&root.join("Cargo.toml")) {
57	            resolver.inheritance().ok().map(std::sync::Arc::new)
58	        } else {
59	            None
60	        }
61	    } else {
62	        None
63	    };
64	
65	    let npm_workspace_kind = callisto_manifests::detect_npm_workspace_kind(root)
66	        .ok()
67	        .flatten();
68	
69	    let ctx = OpenContext {
70	        workspace_root: root,
71	        cargo_workspace,
72	        npm_workspace_kind,
73	    };
74	
75	    for bump in &plan.bumps {
76	        for write in &bump.writes {
77	            match write {
78	                VersionWriteTarget::Manifest(p) => {
79	                    let fmt = callisto_model::ManifestFormat::from_path(p)?;
80	                    let decl =
81	                        callisto_model::ManifestDecl::new(p.clone(), ManifestRole::Canonical, fmt)?;
82	                    let mut handle = open(&decl, &ctx)?;
83	                    handle.write_version(&bump.to, permit)?;
84	                    modified_paths.push(p.clone());
85	                }
86	                VersionWriteTarget::CargoWorkspacePackage { root_manifest } => {
87	                    let mut ws_res = WorkspaceCargoResolver::load(&root.join(root_manifest))?;
88	                    ws_res.write_version(&bump.to, permit)?;
89	                    modified_paths.push(root_manifest.clone());
90	                }
91	            }
92	        }
93	    }
94	
95	    for rewrite in &plan.rewrites {
96	        match &rewrite.key.target {
97	            DepWriteTarget::Manifest(p) => {
98	                let fmt = callisto_model::ManifestFormat::from_path(p)?;
99	                let decl =
100	                    callisto_model::ManifestDecl::new(p.clone(), ManifestRole::Canonical, fmt)?;
101	                let mut handle = open(&decl, &ctx)?;
102	                handle.update_dependency_spec(
103	                    &rewrite.key.name,
104	                    rewrite.key.kind.unwrap_or(callisto_model::DepKind::Runtime),
105	                    rewrite.to.clone(),
106	                    permit,
107	                )?;
108	                modified_paths.push(p.clone());
109	            }
110	            DepWriteTarget::CargoWorkspaceDependency { root_manifest } => {
111	                let mut ws_res = WorkspaceCargoResolver::load(&root.join(root_manifest))?;
112	                ws_res.write_dependency(&rewrite.key.name, rewrite.to.clone(), permit)?;
113	                modified_paths.push(root_manifest.clone());
114	            }
115	        }
116	    }
117	
118	    for cl in &plan.changelog_writes {
119	        let rendered = callisto_changelog::render_section(&cl.input)?;
120	        callisto_changelog::prepend(
121	            root,
122	            &cl.changelog_path,
123	            &cl.input.package.display_name(),
124	            &rendered,
125	            permit,
126	        )?;
127	        modified_paths.push(cl.changelog_path.clone());
128	    }
129	
130	    for cs_path in &plan.consumed_changesets {
131	        let full = root.join(cs_path);
132	        if full.exists() {
133	            fs::remove_file(&full).map_err(|e| {
134	                GraphError::Command(CommandError::Io {
135	                    program: "fs".to_string(),
136	                    message: e.to_string(),
137	                })
138	            })?;
139	            modified_paths.push(cs_path.clone());
140	        }
141	    }
142	
143	    if let Some(ref pre_state) = plan.pre_state_update {
144	        let default_dir = PathBuf::from(".changeset");
145	        let pre_dir = plan
146	            .consumed_changesets
147	            .first()
148	            .and_then(|p| p.parent())
149	            .unwrap_or(&default_dir);
150	        let rel_pre_path = pre_dir.join("pre.json");
151	        let pre_path = root.join(&rel_pre_path);
152	        let text = callisto_format::write_pre_json(pre_state);
153	        callisto_manifests::atomic::atomic_write(&pre_path, &text, permit).map_err(|e| {
154	            GraphError::Command(CommandError::Io {
155	                program: "fs".to_string(),
156	                message: e.to_string(),
157	            })
158	        })?;
159	        modified_paths.push(rel_pre_path);
160	    } else if let Some(rel_pre_path) = &plan.delete_pre_json {
161	        let pre_path = root.join(rel_pre_path);
162	        if pre_path.exists() {
163	            fs::remove_file(&pre_path).map_err(|e| {
164	                GraphError::Command(CommandError::Io {
165	                    program: "fs".to_string(),
166	                    message: e.to_string(),
167	                })
168	            })?;
169	            modified_paths.push(rel_pre_path.clone());
170	        }
171	    }
172	
173	    // Collect the set of ecosystems actively involved in this plan so that
174	    // only the corresponding lockfiles are staged. Staging lockfiles whose
175	    // ecosystem was not touched can sweep up unrelated user changes.
176	    use callisto_model::Ecosystem;
177	    let active_ecosystems: std::collections::HashSet<Ecosystem> = plan
178	        .bumps
179	        .iter()
180	        .filter_map(|b| {
181	            // Prefer the ecosystem declared in the PackageId; fall back to
182	            // inferring it from write targets for Bare (unprefixed) ids.
183	            if let Some(eco) = b.package.ecosystem() {
184	                return Some(eco);
185	            }
186	            // Bare id: derive ecosystem from the write targets.
187	            for write in &b.writes {
188	                let eco = match write {
189	                    VersionWriteTarget::CargoWorkspacePackage { .. } => Ecosystem::Cargo,
190	                    VersionWriteTarget::Manifest(p) => {
191	                        match callisto_model::ManifestFormat::from_path(p) {
192	                            Ok(fmt) => fmt.ecosystem(),
193	                            Err(_) => continue,
194	                        }
195	                    }
196	                };
197	                return Some(eco);
198	            }
199	            None
200	        })
201	        .collect();
202	
203	    // Regenerate lockfiles when the caller requested a refresh. This must run
204	    // BEFORE the git-staging loop so the refreshed files are on disk when they
205	    // are picked up by the staging pass below.
206	    if opts.refresh_lockfiles {
207	        let mut refresh_results: Vec<LockfileRefreshResult> = Vec::new();
208	
209	        if active_ecosystems.contains(&Ecosystem::Cargo) {
210	            let out = runner
211	                .run("cargo", &["update", "--workspace"], root)
212	                .unwrap_or_else(|e| CommandOutput {
213	                    exit_code: None,
214	                    stdout: String::new(),
215	                    stderr: e.to_string(),
216	                });
217	            refresh_results.push(LockfileRefreshResult {
218	                filename: PathBuf::from("Cargo.lock"),
219	                refresh_command: "cargo update --workspace".to_string(),
220	                success: out.success(),
221	                exit_code: out.exit_code,
222	            });
223	        }
224	
225	        if active_ecosystems.contains(&Ecosystem::Pypi) {
226	            if root.join("uv.lock").exists() {
227	                let out = runner
228	                    .run("uv", &["lock"], root)
229	                    .unwrap_or_else(|e| CommandOutput {
230	                        exit_code: None,
231	                        stdout: String::new(),
232	                        stderr: e.to_string(),
233	                    });
234	                refresh_results.push(LockfileRefreshResult {
235	                    filename: PathBuf::from("uv.lock"),
236	                    refresh_command: "uv lock".to_string(),
237	                    success: out.success(),
238	                    exit_code: out.exit_code,
239	                });
240	            } else if root.join("poetry.lock").exists() {
241	                let out = runner
242	                    .run("poetry", &["lock", "--no-update"], root)
243	                    .unwrap_or_else(|e| CommandOutput {
244	                        exit_code: None,
245	                        stdout: String::new(),
246	                        stderr: e.to_string(),
247	                    });
248	                refresh_results.push(LockfileRefreshResult {
249	                    filename: PathBuf::from("poetry.lock"),
250	                    refresh_command: "poetry lock --no-update".to_string(),
251	                    success: out.success(),
252	                    exit_code: out.exit_code,
253	                });
254	            }
255	        }
256	
257	        if !refresh_results.is_empty() {
258	            outcome.lockfile_refresh_results = Some(refresh_results);
259	        }
260	    }
261	
262	    // Map each well-known lockfile to its ecosystem, then include the file
263	    // only when that ecosystem is active and the file exists on disk.
264	    let lockfile_ecosystems: &[(&str, Ecosystem)] = &[
265	        ("Cargo.lock", Ecosystem::Cargo),
266	        ("package-lock.json", Ecosystem::Npm),
267	        ("pnpm-lock.yaml", Ecosystem::Npm),
268	        ("yarn.lock", Ecosystem::Npm),
269	        ("bun.lockb", Ecosystem::Npm),
270	        ("uv.lock", Ecosystem::Pypi),
271	        ("poetry.lock", Ecosystem::Pypi),
272	        ("pdm.lock", Ecosystem::Pypi),
273	        ("Pipfile.lock", Ecosystem::Pypi),
274	    ];
275	    for (lockfile, ecosystem) in lockfile_ecosystems {
276	        if !active_ecosystems.contains(ecosystem) {
277	            continue;
278	        }
279	        let p = PathBuf::from(lockfile);
280	        if root.join(&p).exists() && !modified_paths.contains(&p) {
281	            modified_paths.push(p);
282	        }
283	    }
284	
285	    if !modified_paths.is_empty() {
286	        let (existing, deleted): (Vec<_>, Vec<_>) =
287	            modified_paths.iter().partition(|p| root.join(p).exists());
288	
289	        if !existing.is_empty() {
290	            let mut args = vec!["add", "--"];
291	            let strs: Vec<String> = existing.iter().map(|p| p.display().to_string()).collect();
292	            for s in &strs {
293	                args.push(s);
294	            }
295	            let output = runner.run("git", &args, root)?;
296	            if !output.success() {
297	                return Err(GraphError::Command(CommandError::Failed {
298	                    program: "git".to_string(),
299	                    exit_code: output.exit_code,
300	                    stderr: output.stderr,
301	                }));
302	            }
303	        }
304	
305	        if !deleted.is_empty() {
306	            let mut args = vec!["rm", "--cached", "--ignore-unmatch", "--"];
307	            let strs: Vec<String> = deleted.iter().map(|p| p.display().to_string()).collect();
308	            for s in &strs {
309	                args.push(s);
310	            }
311	            let output = runner.run("git", &args, root)?;
312	            if !output.success() {
313	                return Err(GraphError::Command(CommandError::Failed {
314	                    program: "git".to_string(),
315	                    exit_code: output.exit_code,
316	                    stderr: output.stderr,
317	                }));
318	            }
319	        }
320	
321	        outcome.staged = modified_paths;
322	    }
323	
324	    Ok(outcome)
325	}
