533	    /// When a manifest is already at the plan's target version (from a prior
534	    /// partially-applied run that crashed), `apply_version_plan` must NOT bump
535	    /// it again (which would produce an unplanned 1.1.0 → 1.2.0 bump) and must
536	    /// return `Ok` so the caller can complete the remaining operations safely.
537	    ///
538	    /// The manifest write is skipped, but the path is still pushed to staged so
539	    /// that `git add` re-stages any changes that were made in the prior run.
540	    #[test]
541	    fn apply_is_idempotent_when_manifest_already_at_target_version() {
542	        let dir = tempfile::tempdir().expect("create tempdir");
543	        let root = dir.path();
544	
545	        // Manifest already at 1.1.0 — simulates a prior crashed apply.
546	        let cargo_toml_path = root.join("Cargo.toml");
547	        std::fs::write(
548	            &cargo_toml_path,
549	            "[package]\nname = \"my-crate\"\nversion = \"1.1.0\"\nedition = \"2021\"\n",
550	        )
551	        .unwrap();
552	
553	        // Changeset file that would be consumed.
554	        let changeset_dir = root.join(".changeset");
555	        std::fs::create_dir_all(&changeset_dir).unwrap();
556	        std::fs::write(changeset_dir.join("my-change.md"), "---\nmy-crate: minor\n---\n").unwrap();
557	
558	        let manifest_rel = PathBuf::from("Cargo.toml");
559	        let cs_rel = PathBuf::from(".changeset/my-change.md");
560	
561	        let plan = VersionPlan {
562	            bumps: vec![PlannedBump {
563	                package: PackageId::parse("cargo:my-crate").expect("valid id"),
564	                from: cargo_version("1.0.0"),
565	                to: cargo_version("1.1.0"),
566	                severity: Severity::Minor,
567	                governed_by: None,
568	                reason: None,
569	                writes: vec![VersionWriteTarget::Manifest(manifest_rel.clone())],
570	            }],
571	            consumed_changesets: vec![cs_rel.clone()],
572	            ..Default::default()
573	        };
574	
575	        let permit = ApplyPermit::force_for_tests();
576	        let opts = ApplyOptions::default();
577	        let outcome = apply_version_plan(root, &plan, &NoopRunner, &opts, &permit)
578	            .expect("apply_version_plan must succeed when manifest is already at target version");
579	
580	        // Manifest must stay at 1.1.0, not be bumped to 1.2.0.
581	        let content = std::fs::read_to_string(&cargo_toml_path).unwrap();
582	        assert!(
583	            content.contains("version = \"1.1.0\""),
584	            "manifest must remain at 1.1.0 after idempotent apply; content: {content}"
585	        );
586	
587	        // Changeset file must be deleted.
588	        assert!(
589	            !root.join(&cs_rel).exists(),
590	            "changeset file must be deleted even on an idempotent apply"
591	        );
